node --input-type=module -e '
import { readLabel } from "./cache.mjs";
const disk = new Map(); // persisted local cache that survives a process restart
const storage = { get: async k => disk.has(k) ? disk.get(k) : null, set: async (k, v) => { disk.set(k, v); } };
const T0 = 1_000_000_000;

console.log("--- Probe 1: restart with persisted cache, label source changes at restart ---");
console.log("old worker, t0        :", await readLabel(storage, "k", async () => "OLD", T0));
const loadNew = async () => "NEW";
for (const dt of [1_000, 60_000, 359_999, 360_000, 420_000]) {
  console.log(`new worker, t0+${String(dt).padStart(6)}ms:`, await readLabel(storage, "k", loadNew, T0 + dt));
}
console.log("entry on disk after window:", disk.get("k"));

console.log("\n--- Probe 2: same, but restarted worker clock is 120s behind ---");
disk.clear();
await readLabel(storage, "k", async () => "OLD", T0);
const skew = -120_000;
for (const dt of [360_000, 479_999, 480_000]) {
  console.log(`wall t0+${dt}ms (local ${dt + skew}):`, await readLabel(storage, "k", loadNew, T0 + dt + skew));
}

console.log("\n--- Probe 3: storage miss returns undefined instead of null ---");
try {
  await readLabel({ get: async () => undefined, set: async () => {} }, "k", loadNew, T0);
  console.log("no throw");
} catch (e) { console.log("throws:", e.constructor.name, e.message); }

console.log("\n--- Probe 4: older entry shape (no expiresAt / expiresAt in seconds) ---");
console.log("no expiresAt      :", await readLabel({ get: async () => JSON.stringify({ value: "OLD" }), set: async () => {} }, "k", loadNew, T0));
console.log("expiresAt seconds :", await readLabel({ get: async () => JSON.stringify({ value: "OLD", expiresAt: Math.floor(T0/1000) + 360 }), set: async () => {} }, "k", loadNew, T0));
'
